const strip = (s) => String(s == null ? "" : s).trim();
const num = (v) => {
  if (v == null || v === "") return null;
  const n = Number(String(v).replace(",", "."));
  return isNaN(n) ? null : n;
};
const stab = (v) => {
  const s = strip(v).toLowerCase();
  if (!s) return "-";
  if (s === "running") return "Running";
  if (s === "pass") return "Pass";
  if (s === "fail") return "Fail";
  return "-";
};

let raw = "";
for (const item of $input.all()) {
  raw += strip(item.json.text || item.json.output || item.json.response || "");
}
raw = raw.replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();

let parsed = null;
let ok = false;
try {
  parsed = JSON.parse(raw);
  ok = !!parsed;
} catch (e) {
  ok = false;
}
if (!ok) {
  return [{ json: { ok: false, error: "OpenAI did not return valid JSON - try again or enter the formula manually" } }];
}

const warnings = [];
const missing = (label, v) => { if (v == null || v === "") warnings.push(label + " not found in document - please fill in"); };

const formula = {
  ffs: strip(parsed.ffs),
  kategori: strip(parsed.kategori),
  customer: strip(parsed.customer),
  bj: num(parsed.bj),
  phMin: num(parsed.phMin),
  phMax: num(parsed.phMax),
  viscosity: strip(parsed.viscosity),
  stabTk: stab(parsed.stabTk),
  stabTkul: stab(parsed.stabTkul),
  stabT50: stab(parsed.stabT50),
  stabTm: stab(parsed.stabTm),
  note: strip(parsed.note),
  lines: []
};

missing("Formula code (FFS)", formula.ffs);
missing("Category", formula.kategori);
missing("Customer", formula.customer);
missing("Viscosity", formula.viscosity);
if (formula.bj == null) warnings.push("BJ not found in document - please fill in");

const stabWarn = (key, rawVal) => {
  const r = strip(rawVal);
  if (r && r !== "-" && formula[key] === "-") {
    warnings.push("Stability " + key.slice(4).toUpperCase() + ": unrecognized value '" + r + "' - set to '-'");
  }
};
stabWarn("stabTk", parsed.stabTk);
stabWarn("stabTkul", parsed.stabTkul);
stabWarn("stabT50", parsed.stabT50);
stabWarn("stabTm", parsed.stabTm);

const inLines = Array.isArray(parsed.lines) ? parsed.lines : [];
for (const ln of inLines) {
  const name = strip(ln && ln.materialName);
  const code = strip(ln && ln.materialCode);
  if (!name && !code) continue;
  const pct = num(ln && ln.pct);
  formula.lines.push({ materialName: name, materialCode: code, pct: pct == null ? 0 : pct, note: strip(ln && ln.note) });
}
if (!formula.lines.length) warnings.push("No composition lines found in document - add materials manually");
if (parsed.multiTable === true) warnings.push("Multiple formula tables found - parsed the first one; please verify");

let fileName = "upload.pdf";
try {
  const wh = $("Webhook").first();
  if (wh.binary && wh.binary.file && wh.binary.file.fileName) fileName = wh.binary.file.fileName;
} catch (e) { /* keep fallback */ }

const document = { fileName, pages: null, parser: "openai" };
return [{ json: { ok: true, document, formula, warnings } }];

const items = $input.all();
const j = (items[0] && items[0].json) || {};
let msg;
if (j.error) {
  msg = "Could not read the PDF: " + String(j.error.message || j.error);
} else {
  msg = "This looks like a scanned PDF. Please provide a digitally exported PDF.";
}
return [{ json: { ok: false, error: msg } }];
